e target name syntax is defined in\n // https://github.com/grpc/grpc/blob/master/doc/naming.md.\n // e.g. to use dns resolver, a \"dns:///\" prefix should be applied to the target.\n func DialContext(ctx context.Context, target string, opts ...DialOption) (conn *ClientConn, err error) {\n \tcc := \u0026ClientConn{\n \t\ttarget:            target,\n \t\tcsMgr:             \u0026connectivityStateManager{},\n \t\tconns:             make(map[*addrConn]struct{}),\n \t\tdopts:             defaultDialOptions(),\n \t\tblockingpicker:    newPickerWrapper(),\n \t\tczData:            new(channelzData),\n \t\tfirstResolveEvent: grpcsync.NewEvent(),\n \t}\n \tcc.retryThrottler.Store((*retryThrottler)(nil))\n \tcc.ctx, cc.cancel = context.WithCancel(context.Background())\n \n \tfor _, opt := range opts {\n \t\topt.apply(\u0026cc.dopts)\n \t}\n \n \tdefer func() {\n \t\tif err != nil {\n \t\t\tcc.Close()\n \t\t}\n \t}()\n \n \tif channelz.IsOn() {\n \t\tif cc.dopts.channelzParentID != 0 {\n \t\t\tcc.channelzID = channelz.RegisterChannel(\u0026channelzChannel{cc}, cc.dopts.channelzParentID, target)\n \t\t\tchannelz.AddTraceEvent(cc.channelzID, \u0026channelz.TraceEventDesc{\n \t\t\t\tDesc:     \"Channel Created\",\n \t\t\t\tSeverity: channelz.CtINFO,\n \t\t\t\tParent: \u0026channelz.TraceEventDesc{\n \t\t\t\t\tDesc:     fmt.Sprintf(\"Nested Channel(id:%d) created\", cc.channelzID),\n \t\t\t\t\tSeverity: channelz.CtINFO,\n \t\t\t\t},\n \t\t\t})\n \t\t} else {\n \t\t\tcc.channelzID = channelz.RegisterChannel(\u0026channelzChannel{cc}, 0, target)\n \t\t\tchannelz.AddTraceEvent(cc.channelzID, \u0026channelz.TraceEventDesc{\n \t\t\t\tDesc:     \"Channel Created\",\n \t\t\t\tSeverity: channelz.CtINFO,\n \t\t\t})\n \t\t}\n \t\tcc.csMgr.channelzID = cc.channelzID\n \t}\n \n \tif !cc.dopts.insecure {\n \t\tif cc.dopts.copts.TransportCredentials == nil \u0026\u0026 cc.dopts.copts.CredsBundle == nil {\n \t\t\treturn nil, errNoTransportSecurity\n \t\t}\n \t\tif cc.dopts.copts.TransportCredentials != nil \u0026\u0026 cc.dopts.copts.CredsBundle != nil {\n \t\t\treturn nil, errTransportCredsAndBundle\n \t\t}\n \t} else {\n \t\tif cc.dopts.copts.TransportCredentials != nil || cc.dopts.copts.CredsBundle != nil {\n \t\t\treturn nil, errCredentialsConflict\n \t\t}\n \t\tfor _, cd := range cc.dopts.copts.PerRPCCredentials {\n \t\t\tif cd.RequireTransportSecurity() {\n \t\t\t\treturn nil, errTransportCredentialsMissing\n \t\t\t}\n \t\t}\n \t}\n \n \tif cc.dopts.defaultServiceConfigRawJSON != nil {\n \t\tsc, err := parseServiceConfig(*cc.dopts.defaultServiceConfigRawJSON)\n \t\tif err != nil {\n \t\t\treturn nil, fmt.Errorf(\"%s: %v\", invalidDefaultServiceConfigErrPrefix, err)\n \t\t}\n \t\tcc.dopts.defaultServiceConfig = sc\n \t}\n \tcc.mkp = cc.dopts.copts.KeepaliveParams\n \n \tif cc.dopts.copts.Dialer == nil {\n \t\tcc.dopts.copts.Dialer = newProxyDialer(\n \t\t\tfunc(ctx context.Context, addr string) (net.Conn, error) {\n \t\t\t\tnetwork, addr := parseDialTarget(addr)\n \t\t\t\treturn (\u0026net.Dialer{}).DialContext(ctx, network, addr)\n \t\t\t},\n \t\t)\n \t}\n \n \tif cc.dopts.copts.UserAgent != \"\" {\n \t\tcc.dopts.copts.UserAgent += \" \" + grpcUA\n \t} else {\n \t\tcc.dopts.copts.UserAgent = grpcUA\n \t}\n \n \tif cc.dopts.timeout \u003e 0 {\n \t\tvar cancel context.CancelFunc\n \t\tctx, cancel = context.WithTimeout(ctx, cc.dopts.timeout)\n \t\tdefer cancel()\n \t}\n \tdefer func() {\n \t\tselect {\n \t\tcase \u003c-ctx.Done():\n \t\t\tconn, err = nil, ctx.Err()\n \t\tdefault:\n \t\t}\n \t}()\n \n \tscSet := false\n \tif cc.dopts.scChan != nil {\n \t\t// Try to get an initial service config.\n \t\tselect {\n \t\tcase sc, ok := \u003c-cc.dopts.scChan:\n \t\t\tif ok {\n \t\t\t\tcc.sc = \u0026sc\n \t\t\t\tscSet = true\n \t\t\t}\n \t\tdefault:\n \t\t}\n \t}\n \tif cc.dopts.bs == nil {\n-\t\tcc.dopts.bs = backoff.Exponential{\n-\t\t\tMaxDelay: DefaultBackoffConfig.MaxDelay,\n-\t\t}\n+\t\tcc.dopts.bs = backoff.NewExponentialBuilder().Build()\n \t}\n \tif cc.dopts.resolverBuilder == nil {\n \t\t// Only try to parse target when resolver builder is not already set.\n \t\tcc.parsedTarget = parseTarget(cc.target)\n \t\tgrpclog.Infof(\"parsed scheme: %q\", cc.parsedTarget.Scheme)\n \t\tcc.dopts.resolverBuilder = resolver.Get(cc.parsedTarget.Scheme)\n \t\tif cc.dopts.resolverBuilder == nil {\n \t\t\t// If resolver builder is still nil, the parsed target's scheme is\n \t\t\t// not registered. Fallback to default resolver and set Endpoint to\n \t\t\t// the original target.\n \t\t\tgrpclog.Infof(\"scheme %q not registered, fallback to default scheme\", cc.parsedTarget.Scheme)\n \t\t\tcc.parsedTarget = resolver.Target{\n \t\t\t\tScheme:   resolver.GetDefaultScheme(),\n \t\t\t\tEndpoint: target,\n \t\t\t}\n \t\t\tcc.dopts.resolverBuilder = resolver.Get(cc.parsedTarget.Scheme)\n \t\t}\n \t} else {\n \t\tcc.parsedTarget = resolver.Target{Endpoint: target}\n \t}\n \tcreds := cc.dopts.copts.TransportCredentials\n \tif creds != nil \u0026\u0026 creds.Info().ServerName != \"\" {\n \t\tcc.authority = creds.Info().ServerName\n \t} else if cc.dopts.insecure \u0026\u0026 cc.dopts.authority != \"\" {\n \t\tcc.authority = cc.dopts.authority\n \t} else {\n \t\t// Use endpoint from \"scheme://authority/endpoint\" as the default\n \t\t// authority for ClientConn.\n \t\tcc.authority = cc.parsedTarget.Endpoint\n \t}\n \n \tif cc.dopts.scChan != nil \u0026\u0026 !scSet {\n \t\t// Blocking wait for the initial service config.\n \t\tselect {\n \t\tcase sc, ok := \u003c-cc.dopts.scChan:\n \t\t\tif ok {\n \t\t\t\tcc.sc = \u0026sc\n \t\t\t}\n \t\tcase \u003c-ctx.Done():\n \t\t\treturn nil, ctx.Err()\n \t\t}\n \t}\n \tif cc.dopts.scChan != nil {\n \t\tgo cc.scWatcher()\n \t}\n \n \tvar credsClone credentials.TransportCredentials\n \tif creds := cc.dopts.copts.TransportCredentials; creds != nil {\n \t\tcredsClone = creds.Clone()\n \t}\n \tcc.balancerBuildOpts = balancer.BuildOptions{\n \t\tDialCreds:        credsClone,\n \t\tCredsBundle:      cc.dopts.copts.CredsBundle,\n \t\tDialer:           cc.dopts.copts.Dialer,\n \t\tChannelzParentID: cc.channelzID,\n \t}\n \n \t// Build the resolver.\n \trWrapper, err := newCCResolverWrapper(cc)\n \tif err != nil {\n \t\treturn nil, fmt.Errorf(\"failed to build resolver: %v\", err)\n \t}\n \n \tcc.mu.Lock()\n \tcc.resolverWrapper = rWrapper\n \tcc.mu.Unlock()\n \t// A blocking dial blocks until the clientConn is ready.\n \tif cc.dopts.block {\n \t\tfor {\n \t\t\ts := cc.GetState()\n \t\t\tif s == connectivity.Ready {\n \t\t\t\tbreak\n \t\t\t} else if cc.dopts.copts.FailOnNonTempDialError \u0026\u0026 s == connectivity.TransientFailure {\n \t\t\t\tif err = cc.blockingpicker.connectionError(); err != nil {\n \t\t\t\t\tterr, ok := err.(interface {\n \t\t\t\t\t\tTemporary() bool\n \t\t\t\t\t})\n \t\t\t\t\tif ok \u0026\u0026 !terr.Temporary() {\n \t\t\t\t\t\treturn nil, err\n \t\t\t\t\t}\n \t\t\t\t}\n \t\t\t}\n \t\t\tif !cc.WaitForStateChange(ctx, s) {\n \t\t\t\t// ctx got timeout or canceled.\n \t\t\t\treturn nil, ctx.Err()\n \t\t\t}\n \t\t}\n \t}\n \n \treturn cc, nil\n }\n \n // connectivityStateManager keeps the connectivity.State of ClientConn.\n // This struct will eventually be exported so the balancers can access it.\n type connectivityStateManager struct {\n \tmu         sync.Mutex\n \tstate      connectivity.State\n \tnotifyChan chan struct{}\n \tchannelzID int64\n }\n \n // updateState updates the connectivity.State of ClientConn.\n // If there's a change it notifies goroutines waiting on state change to\n // happen.\n func (csm *connectivityStateManager) updateState(state connectivity.State) {\n \tcsm.mu.Lock()\n \tdefer csm.mu.Unlock()\n \tif csm.state == connectivity.Shutdown {\n \t\treturn\n \t}\n \tif csm.state == state {\n \t\treturn\n \t}\n \tcsm.state = state\n \tif channelz.IsOn() {\n \t\tchannelz.AddTraceEvent(csm.channelzID, \u0026channelz.TraceEventDesc{\n \t\t\tDesc:     fmt.Sprintf(\"Channel Connectivity change to %v\", state),\n \t\t\tSeverity: channelz.CtINFO,\n \t\t})\n \t}\n \tif csm.notifyChan != nil {\n \t\t// There are other goroutines waiting on this channel.\n \t\tclose(csm.notifyChan)\n \t\tcsm.notifyChan = nil\n \t}\n }\n \n func (csm *connectivityStateManager) getState() connectivity.State {\n \tcsm.mu.Lock()\n \tdefer csm.mu.Unlock()\n \treturn csm.state\n }\n \n func (csm *connectivityStateManager) getNotifyChan() \u003c-chan struct{} {\n \tcsm.mu.Lock()\n \tdefer csm.mu.Unlock()\n \tif csm.notifyChan == nil {\n \t\tcsm.notifyChan = make(chan struct{})\n \t}\n \treturn csm.notifyChan\n }\n \n // ClientConn represents a client connection to an RPC server.\n type ClientConn struct {\n \tctx    context.Context\n \tcancel context.CancelFunc\n \n \ttarget       string\n \tparsedTarget resolver.Target\n \tauthority    string\n \tdopts        dialOptions\n \tcsMgr        *connectivityStateManager\n \n \tbalancerBuildOpts balancer.BuildOptions\n \tblockingpicker    *pickerWrapper\n \n \tmu              sync.RWMutex\n \tresolverWrapper *ccResolverWrapper\n \tsc              *ServiceConfig\n \tconns           map[*addrConn]struct{}\n \t// Keepalive parameter can be updated if a GoAway is received.\n \tmkp             keepalive.ClientParameters\n \tcurBalancerName string\n \tbalancerWrapper *ccBalancerWrapper\n \tretryThrottler  atomic.Value\n \n \tfirstResolveEvent *grpcsync.Event\n \n \tchannelzID int64 // channelz unique identification number\n \tczData     *channelzData\n }\n \n // WaitForStateChange waits until the connectivity.State of ClientConn changes from sourceState or\n // ctx expires. A true value is returned in former case and false in latter.\n // This is an EXPERIMENTAL API.\n func (cc *ClientConn) WaitForStateChange(ctx context.Context, sourceState connectivity.State) bool {\n \tch := cc.csMgr.getNotifyChan()\n \tif cc.csMgr.getState() != sourceState {\n \t\treturn true\n \t}\n \tselect {\n \tcase \u003c-ctx.Done():\n \t\treturn false\n \tcase \u003c-ch:\n \t\treturn true\n \t}\n }\n \n // GetState returns the connectivity.State of ClientConn.\n // This is an EXPERIMENTAL API.\n func (cc *ClientConn) GetState() connectivity.State {\n \treturn cc.csMgr.getState()\n }\n \n func (cc *ClientConn) scWatcher() {\n \tfor {\n \t\tselect {\n \t\tcase sc, ok := \u003c-cc.dopts.scChan:\n \t\t\tif !ok {\n \t\t\t\treturn\n \t\t\t}\n \t\t\tcc.mu.Lock()\n \t\t\t// TODO: load balance policy runtime change is ignored.\n \t\t\t// We may revisit this decision in the future.\n \t\t\tcc.sc = \u0026sc\n \t\t\tcc.mu.Unlock()\n \t\tcase \u003c-cc.ctx.Done():\n \t\t\treturn\n \t\t}\n \t}\n }\n \n // waitForResolvedAddrs blocks until the resolver has provided addresses or the\n // context expires.  Returns nil unless the context expires first; otherwise\n // returns a status error based on the context.\n func (cc *ClientConn) waitForResolvedAddrs(ctx context.Context) error {\n \t// This is on the RPC path, so we use a fast path to avoid the\n \t// more-expensive \"select\" below after the resolver has returned once.\n \tif cc.firstResolveEvent.HasFired() {\n \t\treturn nil\n \t}\n \tselect {\n \tcase \u003c-cc.firstResolveEvent.Done():\n \t\treturn nil\n \tcase \u003c-ctx.Done():\n \t\treturn status.FromContextError(ctx.Err()).Err()\n \tcase \u003c-cc.ctx.Done():\n \t\treturn ErrClientConnClosing\n \t}\n }\n \n // gRPC should resort to default service config when:\n // * resolver service config is disabled\n // * or, resolver does not return a service config or returns an invalid one.\n func (cc *ClientConn) fallbackToDefaultServiceConfig(sc string) bool {\n \tif cc.dopts.disableServiceConfig {\n \t\treturn true\n \t}\n \t// The logic below is temporary, will be removed once we change the resolver.State ServiceConfig field type.\n \t// Right now, we assume that empty service config string means resolver does not return a config.\n \tif sc == \"\" {\n \t\treturn true\n \t}\n \t// TODO: the logic below is temporary. Once we finish the logic to validate service config\n \t// in resolver, we will replace the logic below.\n \t_, err := parseServiceConfig(sc)\n \treturn err != nil\n }\n \n func (cc *ClientConn) updateResolverState(s resolver.State) error {\n \tcc.mu.Lock()\n \tdefer cc.mu.Unlock()\n \t// Check if the ClientConn is already closed. Some fields (e.g.\n \t// balancerWrapper) are set to nil when closing the ClientConn, and could\n \t// cause nil pointer panic if we don't have this check.\n \tif cc.conns == nil {\n \t\treturn nil\n \t}\n \n \tif cc.fallbackToDefaultServiceConfig(s.ServiceConfig) {\n \t\tif cc.dopts.defaultServiceConfig != nil \u0026\u0026 cc.sc == nil {\n \t\t\tcc.applyServiceConfig(cc.dopts.defaultServiceConfig)\n \t\t}\n \t} else {\n \t\t// TODO: the parsing logic below will be moved inside resolver.\n \t\tsc, err := parseServiceConfig(s.ServiceConfig)\n \t\tif err != nil {\n \t\t\treturn err\n \t\t}\n \t\tif cc.sc == nil || cc.sc.rawJSONString != s.ServiceConfig {\n \t\t\tcc.applyServiceConfig(sc)\n \t\t}\n \t}\n \n \t// update the service config that will be sent to balancer.\n \tif cc.sc != nil {\n \t\ts.ServiceConfig = cc.sc.rawJSONString\n \t}\n \n \tif cc.dopts.balancerBuilder == nil {\n \t\t// Only look at balancer types and switch balancer if balancer dial\n \t\t// option is not set.\n \t\tvar isGRPCLB bool\n \t\tfor _, a := range s.Addresses {\n \t\t\tif a.Type == resolver.GRPCLB {\n \t\t\t\tisGRPCLB = true\n \t\t\t\tbreak\n \t\t\t}\n \t\t}\n \t\tvar newBalancerName string\n \t\t// TODO: use new loadBalancerConfig field with appropriate priority.\n \t\tif isGRPCLB {\n \t\t\tnewBalancerName = grpclbName\n \t\t} else if cc.sc != nil \u0026\u0026 cc.sc.LB != nil {\n \t\t\tnewBalancerName = *cc.sc.LB\n \t\t} else {\n \t\t\tnewBalancerName = PickFirstBalancerName\n \t\t}\n \t\tcc.switchBalancer(newBalancerName)\n \t} else if cc.balancerWrapper == nil {\n \t\t// Balancer dial option was set, and this is the first time handling\n \t\t// resolved addresses. Build a balancer with dopts.balancerBuilder.\n \t\tcc.balancerWrapper = newCCBalancerWrapper(cc, cc.dopts.balancerBuilder, cc.balancerBuildOpts)\n \t}\n \n \tcc.balancerWrapper.updateResolverState(s)\n \tcc.firstResolveEvent.Fire()\n \treturn nil\n }\n \n // switchBalancer starts the switching from current balancer to the balancer\n // with the given name.\n //\n // It will NOT send the current address list to the new balancer. If needed,\n // caller of this function should send address list to the new balancer after\n // this function returns.\n //\n // Caller must hold cc.mu.\n func (cc *ClientConn) switchBalancer(name string) {\n \tif strings.ToLower(cc.curBalancerName) == strings.ToLower(name) {\n \t\treturn\n \t}\n \n \tgrpclog.Infof(\"ClientConn switching balancer to %q\", name)\n \tif cc.dopts.balancerBuilder != nil {\n \t\tgrpclog.Infoln(\"ignoring balancer switching: Balancer DialOption used instead\")\n \t\treturn\n \t}\n \tif cc.balancerWrapper != nil {\n \t\tcc.balancerWrapper.close()\n \t}\n \n \tbuilder := balancer.Get(name)\n \tif channelz.IsOn() {\n \t\tif builder == nil {\n \t\t\tchannelz.AddTraceEvent(cc.channelzID, \u0026channelz.TraceEventDesc{\n \t\t\t\tDesc:     fmt.Sprintf(\"Channel switches to new LB policy %q due to fallback from invalid balancer name\", PickFirstBalancerName),\n \t\t\t\tSeverity: channelz.CtWarning,\n \t\t\t})\n \t\t} else {\n \t\t\tchannelz.AddTraceEvent(cc.channelzID, \u0026channelz.TraceEventDesc{\n \t\t\t\tDesc:     fmt.Sprintf(\"Channel switches to new LB policy %q\", name),\n \t\t\t\tSeverity: channelz.CtINFO,\n \t\t\t})\n \t\t}\n \t}\n \tif builder == nil {\n \t\tgrpclog.Infof(\"failed to get balancer builder for: %v, using pick_first instead\", name)\n \t\tbuilder = newPickfirstBuilder()\n \t}\n \n \tcc.curBalancerName = builder.Name()\n \tcc.balancerWrapper = newCCBalancerWrapper(cc, builder, cc.balancerBuildOpts)\n }\n \n func (cc *ClientConn) handleSubConnStateChange(sc balancer.SubConn, s connectivity.State) {\n \tcc.mu.Lock()\n \tif cc.conns == nil {\n \t\tcc.mu.Unlock()\n \t\treturn\n \t}\n \t// TODO(bar switching) send updates to all balancer wrappers when balancer\n \t// gracefully switching is supported.\n \tcc.balancerWrapper.handleSubConnStateChange(sc, s)\n \tcc.mu.Unlock()\n }\n \n // newAddrConn creates an addrConn for addrs and adds it to cc.conns.\n //\n // Caller needs to make sure len(addrs) \u003e 0.\n func (cc *ClientConn) newAddrConn(addrs []resolver.Address, opts balancer.NewSubConnOptions) (*addrConn, error) {\n \tac := \u0026addrConn{\n \t\tcc:           cc,\n \t\taddrs:        addrs,\n \t\tscopts:       opts,\n \t\tdopts:        cc.dopts,\n \t\tczData:       new(channelzData),\n \t\tresetBackoff: make(chan struct{}),\n \t}\n \tac.ctx, ac.cancel = context.WithCancel(cc.ctx)\n \t// Track ac in cc. This needs to be done before any getTransport(...) is called.\n \tcc.mu.Lock()\n \tif cc.conns == nil {\n \t\tcc.mu.Unlock()\n \t\treturn nil, ErrClientConnClosing\n \t}\n \tif channelz.IsOn() {\n \t\tac.channelzID = channelz.RegisterSubChannel(ac, cc.channelzID, \"\")\n \t\tchannelz.AddTraceEvent(ac.channelzID, \u0026channelz.TraceEventDesc{\n \t\t\tDesc:     \"Subchannel Created\",\n \t\t\tSeverity: channelz.CtINFO,\n \t\t\tParent: \u0026channelz.TraceEventDesc{\n \t\t\t\tDesc:     fmt.Sprintf(\"Subchannel(id:%d) created\", ac.channelzID),\n \t\t\t\tSeverity: channelz.CtINFO,\n \t\t\t},\n \t\t})\n \t}\n \tcc.conns[ac] = struct{}{}\n \tcc.mu.Unlock()\n \treturn ac, nil\n }\n \n // removeAddrConn removes the addrConn in the subConn from clientConn.\n // It also tears down the ac with the given error.\n func (cc *ClientConn) removeAddrConn(ac *addrConn, err error) {\n \tcc.mu.Lock()\n \tif cc.conns == nil {\n \t\tcc.mu.Unlock()\n \t\treturn\n \t}\n \tdelete(cc.conns, ac)\n \tcc.mu.Unlock()\n \tac.tearDown(err)\n }\n \n func (cc *ClientConn) channelzMetric() *channelz.ChannelInternalMetric {\n \treturn \u0026channelz.ChannelInternalMetric{\n \t\tState:                    cc.GetState(),\n \t\tTarget:                   cc.target,\n \t\tCallsStarted:             atomic.LoadInt64(\u0026cc.czData.callsStarted),\n \t\tCallsSucceeded:           atomic.LoadInt64(\u0026cc.czData.callsSucceeded),\n \t\tCallsFailed:              atomic.LoadInt64(\u0026cc.czData.callsFailed),\n \t\tLastCallStartedTimestamp: time.Unix(0, atomic.LoadInt64(\u0026cc.czData.lastCallStartedTime)),\n \t}\n }\n \n // Target returns the target string of the ClientConn.\n // This is an EXPERIMENTAL API.\n func (cc *ClientConn) Target() string {\n \treturn cc.target\n }\n \n func (cc *ClientConn) incrCallsStarted() {\n \tatomic.AddInt64(\u0026cc.czData.callsStarted, 1)\n \tatomic.StoreInt64(\u0026cc.czData.lastCallStartedTime, time.Now().UnixNano())\n }\n \n func (cc *ClientConn) incrCallsSucceeded() {\n \tatomic.AddInt64(\u0026cc.czData.callsSucceeded, 1)\n }\n \n func (cc *ClientConn) incrCallsFailed() {\n \tatomic.AddInt64(\u0026cc.czData.callsFailed, 1)\n }\n \n // connect starts creating a transport.\n // It does nothing if the ac is not IDLE.\n // TODO(bar) Move this to the addrConn section.\n func (ac *addrConn) connect() error {\n \tac.mu.Lock()\n \tif ac.state == connectivity.Shutdown {\n \t\tac.mu.Unlock()\n \t\treturn errConnClosing\n \t}\n \tif ac.state != connectivity.Idle {\n \t\tac.mu.Unlock()\n \t\treturn nil\n \t}\n \tac.updateConnectivityState(connectivity.Connecting)\n \tac.mu.Unlock()\n \n \t// Start a goroutine connecting to the server asynchronously.\n \tgo ac.resetTransport()\n \treturn nil\n }\n \n // tryUpdateAddrs tries to update ac.addrs with the new addresses list.\n //\n // It checks whether current connected address of ac is in the new addrs list.\n-//  - If true, it updates ac.addrs and returns true. The ac will keep using\n-//    the existing connection.\n-//  - If false, it does nothing and returns false.\n+//   - If true, it updates ac.addrs and returns true. The ac will keep using\n+//     the existing connection.\n+//   - If false, it does nothing and returns false.\n func (ac *addrConn) tryUpdateAddrs(addrs []resolver.Address) bool {\n \tac.mu.Lock()\n \tdefer ac.mu.Unlock()\n \tgrpclog.Infof(\"addrConn: tryUpdateAddrs curAddr: %v, addrs: %v\", ac.curAddr, addrs)\n \tif ac.state == connectivity.Shutdown {\n \t\tac.addrs = addrs\n \t\treturn true\n \t}\n \n \t// Unless we're busy reconnecting already, let's reconnect from the top of\n \t// the list.\n \tif ac.state != connectivity.Ready {\n \t\treturn false\n \t}\n \n \tvar curAddrFound bool\n \tfor _, a := range addrs {\n \t\tif reflect.DeepEqual(ac.curAddr, a) {\n \t\t\tcurAddrFound = true\n \t\t\tbreak\n \t\t}\n \t}\n \tgrpclog.Infof(\"addrConn: tryUpdateAddrs curAddrFound: %v\", curAddrFound)\n \tif curAddrFound {\n \t\tac.addrs = addrs\n \t}\n \n \treturn curAddrFound\n }\n \n // GetMethodConfig gets the method config of the input method.\n // If there's an exact match for input method (i.e. /service/method), we return\n // the corresponding MethodConfig.\n // If there isn't an exact match for the input method, we look for the default config\n // under the service (i.e /service/). If there is a default MethodConfig for\n // the service, we return it.\n // Otherwise, we return an empty MethodConfig.\n func (cc *ClientConn) GetMethodConfig(method string) MethodConfig {\n \t// TODO: Avoid the locking here.\n \tcc.mu.RLock()\n \tdefer cc.mu.RUnlock()\n \tif cc.sc == nil {\n \t\treturn MethodConfig{}\n \t}\n \tm, ok := cc.sc.Methods[method]\n \tif !ok {\n \t\ti := strings.LastIndex(method, \"/\")\n \t\tm = cc.sc.Methods[method[:i+1]]\n \t}\n \treturn m\n }\n \n func (cc *ClientConn) healthCheckConfig() *healthCheckConfig {\n \tcc.mu.RLock()\n \tdefer cc.mu.RUnlock()\n \tif cc.sc == nil {\n \t\treturn nil\n \t}\n \treturn cc.sc.healthCheckConfig\n }\n \n func (cc *ClientConn) getTransport(ctx context.Context, failfast bool, method string) (transport.ClientTransport, func(balancer.DoneInfo), error) {\n \tt, done, err := cc.blockingpicker.pick(ctx, failfast, balancer.PickOptions{\n \t\tFullMethodName: method,\n \t})\n \tif err != nil {\n \t\treturn nil, nil, toRPCErr(err)\n \t}\n \treturn t, done, nil\n }\n \n func (cc *ClientConn) applyServiceConfig(sc *ServiceConfig) error {\n \tif sc == nil {\n \t\t// should never reach here.\n \t\treturn fmt.Errorf(\"got nil pointer for service config\")\n \t}\n \tcc.sc = sc\n \n \tif cc.sc.retryThrottling != nil {\n \t\tnewThrottler := \u0026retryThrottler{\n \t\t\ttokens: cc.sc.retryThrottling.MaxTokens,\n \t\t\tmax:    cc.sc.retryThrottling.MaxTokens,\n \t\t\tthresh: cc.sc.retryThrottling.MaxTokens / 2,\n \t\t\tratio:  cc.sc.retryThrottling.TokenRatio,\n \t\t}\n \t\tcc.retryThrottler.Store(newThrottler)\n \t} else {\n \t\tcc.retryThrottler.Store((*retryThrottler)(nil))\n \t}\n \n \treturn nil\n }\n \n func (cc *ClientConn) resolveNow(o resolver.ResolveNowOption) {\n \tcc.mu.RLock()\n \tr := cc.resolverWrapper\n \tcc.mu.RUnlock()\n \tif r == nil {\n \t\treturn\n \t}\n \tgo r.resolveNow(o)\n }\n \n // ResetConnectBackoff wakes up all subchannels in transient failure and causes\n // them to attempt another connection immediately.  It also resets the backoff\n // times used for subsequent attempts regardless of the current state.\n //\n // In general, this function should not be used.  Typical service or network\n // outages result in a reasonable client reconnection strategy by default.\n // However, if a previously unavailable network becomes available, this may be\n // used to trigger an immediate reconnect.\n //\n // This API is EXPERIMENTAL.\n func (cc *ClientConn) ResetConnectBackoff() {\n \tcc.mu.Lock()\n \tdefer cc.mu.Unlock()\n \tfor ac := range cc.conns {\n \t\tac.resetConnectBackoff()\n \t}\n }\n \n // Close tears down the ClientConn and all underlying connections.\n func (cc *ClientConn) Close() error {\n \tdefer cc.cancel()\n \n \tcc.mu.Lock()\n \tif cc.conns == nil {\n \t\tcc.mu.Unlock()\n \t\treturn ErrClientConnClosing\n \t}\n \tconns := cc.conns\n \tcc.conns = nil\n \tcc.csMgr.updateState(connectivity.Shutdown)