e connectivity.State\n \n \tbackoffIdx   int // Needs to be stateful for resetConnectBackoff.\n \tresetBackoff chan struct{}\n \n \tchannelzID int64 // channelz unique identification number.\n \tczData     *channelzData\n }\n \n // Note: this requires a lock on ac.mu.\n func (ac *addrConn) updateConnectivityState(s connectivity.State) {\n \tif ac.state == s {\n \t\treturn\n \t}\n \n \tupdateMsg := fmt.Sprintf(\"Subchannel Connectivity change to %v\", s)\n \tac.state = s\n \tif channelz.IsOn() {\n \t\tchannelz.AddTraceEvent(ac.channelzID, \u0026channelz.TraceEventDesc{\n \t\t\tDesc:     updateMsg,\n \t\t\tSeverity: channelz.CtINFO,\n \t\t})\n \t}\n \tac.cc.handleSubConnStateChange(ac.acbw, s)\n }\n \n // adjustParams updates parameters used to create transports upon\n // receiving a GoAway.\n func (ac *addrConn) adjustParams(r transport.GoAwayReason) {\n \tswitch r {\n \tcase transport.GoAwayTooManyPings:\n \t\tv := 2 * ac.dopts.copts.KeepaliveParams.Time\n \t\tac.cc.mu.Lock()\n \t\tif v \u003e ac.cc.mkp.Time {\n \t\t\tac.cc.mkp.Time = v\n \t\t}\n \t\tac.cc.mu.Unlock()\n \t}\n }\n \n func (ac *addrConn) resetTransport() {\n \tfor i := 0; ; i++ {\n \t\tif i \u003e 0 {\n \t\t\tac.cc.resolveNow(resolver.ResolveNowOption{})\n \t\t}\n \n \t\tac.mu.Lock()\n \t\tif ac.state == connectivity.Shutdown {\n \t\t\tac.mu.Unlock()\n \t\t\treturn\n \t\t}\n \n \t\taddrs := ac.addrs\n \t\tbackoffFor := ac.dopts.bs.Backoff(ac.backoffIdx)\n \t\t// This will be the duration that dial gets to finish.\n-\t\tdialDuration := minConnectTimeout\n+\t\tdialDuration := ac.dopts.mct\n \t\tif ac.dopts.minConnectTimeout != nil {\n \t\t\tdialDuration = ac.dopts.minConnectTimeout()\n \t\t}\n \n \t\tif dialDuration \u003c backoffFor {\n \t\t\t// Give dial more time as we keep failing to connect.\n \t\t\tdialDuration = backoffFor\n \t\t}\n \t\t// We can potentially spend all the time trying the first address, and\n \t\t// if the server accepts the connection and then hangs, the following\n \t\t// addresses will never be tried.\n \t\t//\n \t\t// The spec doesn't mention what should be done for multiple addresses.\n \t\t// https://github.com/grpc/grpc/blob/master/doc/connection-backoff.md#proposed-backoff-algorithm\n \t\tconnectDeadline := time.Now().Add(dialDuration)\n \t\tac.mu.Unlock()\n \n \t\tnewTr, addr, reconnect, err := ac.tryAllAddrs(addrs, connectDeadline)\n \t\tif err != nil {\n \t\t\t// After exhausting all addresses, the addrConn enters\n \t\t\t// TRANSIENT_FAILURE.\n \t\t\tac.mu.Lock()\n \t\t\tif ac.state == connectivity.Shutdown {\n \t\t\t\tac.mu.Unlock()\n \t\t\t\treturn\n \t\t\t}\n \t\t\tac.updateConnectivityState(connectivity.TransientFailure)\n \n \t\t\t// Backoff.\n \t\t\tb := ac.resetBackoff\n \t\t\tac.mu.Unlock()\n \n \t\t\ttimer := time.NewTimer(backoffFor)\n \t\t\tselect {\n \t\t\tcase \u003c-timer.C:\n \t\t\t\tac.mu.Lock()\n \t\t\t\tac.backoffIdx++\n \t\t\t\tac.mu.Unlock()\n \t\t\tcase \u003c-b:\n \t\t\t\ttimer.Stop()\n \t\t\tcase \u003c-ac.ctx.Done():\n \t\t\t\ttimer.Stop()\n \t\t\t\treturn\n \t\t\t}\n \t\t\tcontinue\n \t\t}\n \n \t\tac.mu.Lock()\n \t\tif ac.state == connectivity.Shutdown {\n \t\t\tnewTr.Close()\n \t\t\tac.mu.Unlock()\n \t\t\treturn\n \t\t}\n \t\tac.curAddr = addr\n \t\tac.transport = newTr\n \t\tac.backoffIdx = 0\n \n \t\thealthCheckConfig := ac.cc.healthCheckConfig()\n \t\t// LB channel health checking is only enabled when all the four requirements below are met:\n \t\t// 1. it is not disabled by the user with the WithDisableHealthCheck DialOption,\n \t\t// 2. the internal.HealthCheckFunc is set by importing the grpc/healthcheck package,\n \t\t// 3. a service config with non-empty healthCheckConfig field is provided,\n \t\t// 4. the current load balancer allows it.\n \t\thctx, hcancel := context.WithCancel(ac.ctx)\n \t\thealthcheckManagingState := false\n \t\tif !ac.cc.dopts.disableHealthCheck \u0026\u0026 healthCheckConfig != nil \u0026\u0026 ac.scopts.HealthCheckEnabled {\n \t\t\tif ac.cc.dopts.healthCheckFunc == nil {\n \t\t\t\t// TODO: add a link to the health check doc in the error message.\n \t\t\t\tgrpclog.Error(\"the client side LB channel health check function has not been set.\")\n \t\t\t} else {\n \t\t\t\t// TODO(deklerk) refactor to just return transport\n \t\t\t\tgo ac.startHealthCheck(hctx, newTr, addr, healthCheckConfig.ServiceName)\n \t\t\t\thealthcheckManagingState = true\n \t\t\t}\n \t\t}\n \t\tif !healthcheckManagingState {\n \t\t\tac.updateConnectivityState(connectivity.Ready)\n \t\t}\n \t\tac.mu.Unlock()\n \n \t\t// Block until the created transport is down. And when this happens,\n \t\t// we restart from the top of the addr list.\n \t\t\u003c-reconnect.Done()\n \t\thcancel()\n \n \t\t// Need to reconnect after a READY, the addrConn enters\n \t\t// TRANSIENT_FAILURE.\n \t\t//\n \t\t// This will set addrConn to TRANSIENT_FAILURE for a very short period\n \t\t// of time, and turns CONNECTING. It seems reasonable to skip this, but\n \t\t// READY-CONNECTING is not a valid transition.\n \t\tac.mu.Lock()\n \t\tif ac.state == connectivity.Shutdown {\n \t\t\tac.mu.Unlock()\n \t\t\treturn\n \t\t}\n \t\tac.updateConnectivityState(connectivity.TransientFailure)\n \t\tac.mu.Unlock()\n \t}\n }\n \n // tryAllAddrs tries to creates a connection to the addresses, and stop when at the\n // first successful one. It returns the transport, the address and a Event in\n // the successful case. The Event fires when the returned transport disconnects.\n func (ac *addrConn) tryAllAddrs(addrs []resolver.Address, connectDeadline time.Time) (transport.ClientTransport, resolver.Address, *grpcsync.Event, error) {\n \tfor _, addr := range addrs {\n \t\tac.mu.Lock()\n \t\tif ac.state == connectivity.Shutdown {\n \t\t\tac.mu.Unlock()\n \t\t\treturn nil, resolver.Address{}, nil, errConnClosing\n \t\t}\n \t\tac.updateConnectivityState(connectivity.Connecting)\n \t\tac.transport = nil\n \n \t\tac.cc.mu.RLock()\n \t\tac.dopts.copts.KeepaliveParams = ac.cc.mkp\n \t\tac.cc.mu.RUnlock()\n \n \t\tcopts