 		serviceName:  serviceName,
 		enableCDS:    enableCDS,
 		opts:         opts,
 		newADS:       newADS,
 		loseContact:  loseContact,
 		cleanup:      exitCleanup,
-		backoff:      defaultBackoffConfig,
+		backoff:      defaultBackoffStrategy,
 	}

 	c.ctx, c.cancel = context.WithCancel(context.Background())

 	return c
